  3	let source = Option.get (App_types.Source.of_string_opt "files:test")
  4	let src locator = App_types.Src_doc.of_source_doc_exn { source; locator }
  5	
  6	let text =
  7	  "The quick brown fox jumps over the lazy dog while a second fox waits \
  8	   patiently nearby watching every single move with great interest today"
  9	
 10	let put db path contents =
 11	  fst (Text.add_file db (src path) { Util.Text_source.name = path; contents })
 12	
 13	let with_db f =
 14	  Sqlite_util.Connect.with_connection Memory (fun db ->
 15	      Text.create_tables db;
 16	      Text.put_source db source;
 17	      f db)
 18	
 19	let capture run =
 20	  Util.Log.with_file ~name:"relocation" run;
 21	  let file =
 22	    Sys.readdir "logs" |> Array.to_list
 23	    |> List.find (String.ends_with ~suffix:"_relocation.log")
 24	  in
 25	  In_channel.with_open_bin (Filename.concat "logs" file) In_channel.input_all
 26	
 27	let check_contains data snippets =
 28	  List.iter
 29	    (fun sub ->
 30	      if not (Testo.contains_substring ~sub data) then
 31	        Testo.fail
 32	          (Printf.sprintf "Missing %S in relocation log:\n%s" sub data))
 33	    snippets
 34	
 35	let position data sub =
 36	  let rec find i =
 37	    if i + String.length sub > String.length data then
 38	      Testo.fail ("Missing " ^ sub)
 39	    else if String.sub data i (String.length sub) = sub then i
 40	    else find (i + 1)
 41	  in
 42	  find 0
